import 'package:flutter/material.dart';
import '../services/api_service.dart';
class MessagesScreen extends StatefulWidget{const MessagesScreen({super.key});@override State<MessagesScreen> createState()=>_MessagesScreenState();}
class _MessagesScreenState extends State<MessagesScreen>{late Future<List<dynamic>> f;@override void initState(){super.initState();f=ApiService.messages();}void reload()=>setState(()=>f=ApiService.messages());Future<void> newMessage()async{final s=TextEditingController(),b=TextEditingController();await showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Contact the clinic'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:s,decoration:const InputDecoration(labelText:'Subject')),TextField(controller:b,maxLines:5,decoration:const InputDecoration(labelText:'Message'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),ElevatedButton(onPressed:()async{if(s.text.trim().isEmpty||b.text.trim().isEmpty)return;await ApiService.sendMessage(s.text.trim(),b.text.trim());if(c.mounted)Navigator.pop(c);reload();},child:const Text('Send'))]));s.dispose();b.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Messages')),floatingActionButton:FloatingActionButton(onPressed:newMessage,child:const Icon(Icons.edit)),body:FutureBuilder(future:f,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final l=s.data!;if(l.isEmpty)return const Center(child:Text('No conversations yet.'));return ListView.builder(padding:const EdgeInsets.all(12),itemCount:l.length,itemBuilder:(c,i){final x=l[i];return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.chat_bubble_outline)),title:Text(x['subject']??'General enquiry',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(x['last_message']??'',maxLines:2,overflow:TextOverflow.ellipsis),trailing:Icon(x['status']=='open'?Icons.chevron_right:Icons.lock_outline),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ConversationScreen(id:x['id']))));});}));}
}
class ConversationScreen extends StatefulWidget{final int id;const ConversationScreen({super.key,required this.id});@override State<ConversationScreen> createState()=>_ConversationScreenState();}
class _ConversationScreenState extends State<ConversationScreen>{late Future<Map<String,dynamic>> f;final c=TextEditingController();@override void initState(){super.initState();f=ApiService.conversation(widget.id);}@override void dispose(){c.dispose();super.dispose();}Future<void> send()async{if(c.text.trim().isEmpty)return;await ApiService.reply(widget.id,c.text.trim());c.clear();setState(()=>f=ApiService.conversation(widget.id));}@override Widget build(BuildContext cxt)=>Scaffold(appBar:AppBar(title:const Text('Conversation')),body:FutureBuilder(future:f,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!;final msgs=d['messages']??[];return Column(children:[Expanded(child:ListView.builder(padding:const EdgeInsets.all(14),itemCount:msgs.length,itemBuilder:(c,i){final m=msgs[i];final mine=m['sender_type']=='patient';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(13),constraints:const BoxConstraints(maxWidth:330),decoration:BoxDecoration(color:mine?const Color(0xFF1A5276):Colors.white,borderRadius:BorderRadius.circular(16)),child:Text(m['body']??'',style:TextStyle(color:mine?Colors.white:Colors.black87)));})),SafeArea(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:c,decoration:const InputDecoration(hintText:'Write a message...'))),IconButton(onPressed:send,icon:const Icon(Icons.send,color:Color(0xFF1A5276))) ])))]);});}
}
